// write path: one atomic INCR per view — key = product + day, TTL so buckets die
$bucket = 'views:product:12:2026-06-01';
$count  = Redis::incr($bucket);

if ($count === 1) {
    Redis::expire($bucket, 60 * 60 * 26);   // stale buckets self-expire
    Redis::sadd('views:pending', 12);       // product now has unsynced views
}

// drain job (scheduler / queue): push each product's delta to MySQL once.
// Storing the last-flushed value next to the count makes the flush idempotent.
foreach (Redis::smembers('views:pending') as $productId) {
    $key     = 'views:product:' . $productId . ':' . date('Y-m-d');
    $current = (int) Redis::get($key);
    $flushed = (int) Redis::get($key . ':flushed');
    $delta   = $current - $flushed;

    if ($delta > 0) {
        DB::table('product_views')
            ->where('product_id', (int) $productId)
            ->increment('views', $delta);

        Redis::set($key . ':flushed', $current);
        Redis::expire($key . ':flushed', 60 * 60 * 26);  // same clock as the bucket
    }

    if ($delta === 0 && $current === 0) {
        Redis::srem('views:pending', $productId);        // nothing left to flush
    }
}

function parse_ttl(string $ttl): ?int
{
    $ttl = trim($ttl);

    if ($ttl === '') {
        return null;
    }

    if (! preg_match('/^(\d+)([smhd])?$/', $ttl, $m)) {
        return null;
    }

    $n    = (int) $m[1];
    $unit = $m[2] ?? 's';
    $mult = ['s' => 1, 'm' => 60, 'h' => 3600, 'd' => 86400];

    return $n * $mult[$unit];
}

