function rebuild_report(string $key): array
{
    $lock = Cache::lock($key, 10);

    if (! $lock->get()) {
        // We lost the race: wait briefly for the winner instead of recomputing.
        $value = Cache::lock($key, 10)->block(3, fn () => compute_and_cache($key));

        return $value !== false ? $value : stale_report();
    }

    try {
        // Double-checked locking: the winner may have stored it while we queued.
        $value = Cache::get($key);

        if ($value === null) {
            $value = expensive_report();
            Cache::put($key, $value, 600);
        }

        return $value;
    } finally {
        $lock->release();
    }
}

function should_recompute(bool $cacheHit, bool $holdsLock): bool
{
